    oral: r => { const x = ri(r, -5, 5) || 2, y = ri(r, -5, 5) || -3; return { q: `В какой четверти точка (${M(x)}; ${M(y)})?`, a: x > 0 && y > 0 ? "I" : x < 0 && y > 0 ? "II" : x < 0 ? "III" : "IV" }; },
