      if (l === 2) { const t = k * n + b; return { q: `Последовательность задана формулой aₙ = ${poly([k, "n"], [b, ""])}. Является ли число ${M(t)} её членом? Если да, укажите номер.`, a: `да, ${n}-й член` }; }
