    oral: r => { const n = ri(r, 4, 12), k = ri(r, 0, 2); if (k === 1) { const d = pick(r, [[2, 2, 2], [3, 3, 2, 2], [1, 1, 2]]); return { q: `Степени вершин графа ${d.join(", ")}. Сколько у него рёбер?`, a: String(d.reduce((a, b) => a + b, 0) / 2) }; } if (k === 2) return { q: `Вершина имеет степень ${n}. Сколько рёбер из неё выходит?`, a: String(n) }; return { q: `Сколько рёбер в дереве с ${n} вершинами?`, a: String(n - 1) }; },
